from validate import validate_record


def process_rows(rows):
    results = []
    for row in rows:
        try:
            results.append(validate_record(row))
        except ValueError:
            continue
    return results


def average_score(rows):
    records = process_rows(rows)
    if not records:
        return 0.0
    total = sum(r['score'] for r in records)
    return round(total / len(records), 2)
